insert into chunks (document_id, chunk_index, heading, content) values
('75f32510-475f-454b-aa80-b275b49f9828', 0, 'CÍL', 'Cílem tohoto standardu je zaručit, že pro rezervy, podmíněné závazky a podmíněná aktiva budou použita vhodná kritéria uznávání a oceňování báze a že budou v komentáři k účetní závěrce zveřejněny dostatečné informace umožňující uživatelům porozumět jejich podstatě, časovému rozvržení a hodnotě.'),
('75f32510-475f-454b-aa80-b275b49f9828', 1, 'ROZSAH PŮSOBNOSTI', '1 a) vyplývají z nesplněných smluv, s výjimkou nevýhodných, a b) [zrušeno]; c) jsou řešeny jinými standardy. 2 3 4 5 a) [zrušeno]; b) daně ze zisku (viz IAS 12 Daně ze zisku); c) leasingy (viz IFRS 16 Leasingy). Tento standard se však použije na jakýkoli leasing, který se stane nevýhodným přede dnem zahájení leasingu podle definice v IFRS 16. Tento standard se rovněž použije na krátkodobé leasingy a leasingy, jejichž podkladové aktivum má nízkou hodnotu účtované v souladu s odstavcem 6 IFRS 16 a které se staly nevýhodnými; d) zaměstnanecké požitky (viz IAS 19 Zaměstnanecké požitky); e) pojistné smlouvy a jiné smlouvy, které spadají do rozsahu působnosti IFRS 17 Pojistné smlouvy; f) podmíněné protihodnoty hrazené nebo inkasované nabyvatelem při podnikových kombinacích (viz IFRS 3 Podnikové kombinace) a g) výnosy ze smluv se zákazníky (viz IFRS 15 Výnosy ze smluv se zákazníky). Na druhou stranu však IFRS 15 neobsahuje žádné specifické požadavky, jak nakládat se smlouvami se zákazníky, které jsou, nebo se staly nevýhodnými, a proto se v těchto případech použije tento standard. 6 7 8 9'),
('75f32510-475f-454b-aa80-b275b49f9828', 2, 'DEFINICE', '10 Rezerva je závazek s nejistým časovým rozvrhem a výší. Závazek  (23) je současná povinnost účetní jednotky, která vznikla jako důsledek události v minulosti a jejíž vypořádání způsobí účetní jednotce odtok prostředků představujících ekonomický prospěch. Událost zakládající závazek je taková událost, která zakládá právní nebo mimosmluvní závazek, jehož důsledkem je skutečnost, že účetní jednotka nemá žádnou reálnou alternativu, než jej vypořádat. Právní závazek je závazek, který vzniká ze: a) smlouvy (prostřednictvím jejích explicitních i implicitních ustanovení); b) právních předpisů nebo c) jiných právních ustanovení. Mimosmluvní závazek je závazek, který vzniká z takových aktivit účetní jednotky, kde: a) účetní jednotka dává zavedeným způsobem chování v minulosti, zveřejněnými pravidly nebo dostatečně konkrétním a rozšířeným oznámením třetím stranám najevo, že uzná své konkrétní závazky, a b) v důsledku toho vytvořila účetní jednotka u části těchto třetích stran reálné očekávání, že takové závazky budou vypořádány. Podmíněný závazek je: a) pravděpodobný závazek, který vzniká jako důsledek událostí v minulosti a jehož existence bude potvrzena pouze tím, že dojde nebo nedojde k jedné nebo více nejistým událostem v budoucnosti, které nejsou plně pod kontrolou účetní jednotky, nebo b) současný závazek, který vznikl jako důsledek událostí v minulosti, avšak není uznán, protože: i) není pravděpodobné, že k vypořádání závazku bude nezbytný odtok prostředků představujících ekonomický užitek, nebo ii) výše závazku nemůže být s dostatečnou mírou spolehlivosti vyčíslena.'),
('75f32510-475f-454b-aa80-b275b49f9828', 3, 'DEFINICE', 'Podmíněné aktivum je možné aktivum, které vzniklo jako důsledek událostí v minulosti a jehož existence bude potvrzena pouze tím, že dojde nebo nedojde k jedné nebo více nejistým událostem v budoucnosti, které nejsou plně pod kontrolou účetní jednotky. Nevýhodná smlouva je taková smlouva, u které nevyhnutelné náklady nutné ke splnění smluvních povinností převyšují ekonomický prospěch, jehož získání je na základě smlouvy očekáváno. Restrukturalizace je program, který je plánován a řízen vedením účetní jednotky a významně mění buď: a) předmět podnikání prováděného účetní jednotkou, nebo b) způsob, kterým je podnikání vedeno. Rezervy a ostatní závazky 11 a) obchodní závazky jsou závazky zaplatit zboží nebo služby, které byly dodány nebo přijaty a byly fakturovány nebo jinak formálně odsouhlaseny s dodavatelem, a b) přechodná pasiva jsou závazky zaplatit zboží nebo služby, které byly dodány nebo přijaty a nebyly zaplaceny, fakturovány nebo jinak formálně odsouhlaseny s dodavatelem, včetně částek splatných zaměstnancům (například částky vztahující se k nevybraným dovoleným). Přestože i v případě přechodných aktiv je někdy nezbytné odhadnout jejich částku nebo časové rozvržení, je míra jejich neurčitosti obecně mnohem menší než v případě rezerv. Přechodná pasiva jsou mnohdy vykazována jako součást obchodních a ostatních závazků, zatímco rezervy jsou vykazovány odděleně. Vztah mezi rezervami a podmíněnými závazky'),
('75f32510-475f-454b-aa80-b275b49f9828', 4, 'DEFINICE', '12 13 a) rezervami – které jsou uznány jako závazky (za předpokladu, že může být provedeno jejich spolehlivé vyčíslení), protože jsou současným závazkem a je pravděpodobné, že k vyrovnání takového závazku bude potřebný odtok prostředků představujících ekonomický prospěch, a b) podmíněnými závazky – které nejsou uznány jako závazek, protože jsou buď: i) eventuálními závazky, u nichž musí být teprve potvrzeno, zda má účetní jednotka současný závazek, který povede k odtoku prostředků představujících ekonomický prospěch, nebo ii) současnými závazky, které nesplňují kritéria uznání stanovená tímto standardem (protože buď není pravděpodobné, že bude k jejich vyrovnání nezbytný odtok prostředků představujících ekonomický prospěch, nebo nemůže být provedeno dostatečně spolehlivé vyčíslení výše závazku).'),
('75f32510-475f-454b-aa80-b275b49f9828', 5, 'UZNÁVÁNÍ', 'Rezervy 14 a) má účetní jednotka současný závazek (právní nebo mimosmluvní), který je důsledkem minulé události; b) je pravděpodobné, že k vyrovnání závazku bude nezbytný odtok prostředků představujících ekonomický prospěch, a c) může být proveden spolehlivý odhad výše závazku. Pokud nejsou tyto podmínky splněny, žádné rezervy se neuznají. Současný závazek 15 16 a) uzná rezervu v případě, že je spíše pravděpodobné než nepravděpodobné, že ke konci účetního období současný závazek existuje (a pokud jsou splněna kritéria uznání), a b) zveřejní podmíněný závazek v případě, že je pravděpodobnější, že současný závazek ke konci účetního období neexistuje a pokud odtok prostředků představujících ekonomický prospěch není příliš malý (viz odstavec 86). Minulá událost 17 a) vypořádání závazku je právně vymahatelné, nebo b) v případě mimosmluvních závazků vytváří událost (kterou může být krok účetní jednotky) u třetích stran reálná očekávání, že účetní jednotka závazek splní. 18 19 20 21 22 Pravděpodobný odtok prostředků představujících ekonomický prospěch 23 24 Spolehlivý odhad závazku 25 26 Podmíněné závazky 27 28 29 30 Podmíněná aktiva 31 32 33 34 35'),
('75f32510-475f-454b-aa80-b275b49f9828', 6, 'OCEŇOVÁNÍ', 'Nejlepší odhad 36 37 38 39 Příklad Účetní jednotka prodává zboží se zárukou, na základě které má zákazník kryty veškeré náklady na opravu jakýchkoliv výrobních vad, které se vyskytnou v průběhu prvních šesti měsíců po koupi. Pokud se vyskytnou drobné závady ve všech prodaných výrobcích, bude to znamenat náklady na opravu ve výši 1 milionu. Pokud se vyskytnou velké závady ve všech prodaných výrobcích, bude to znamenat náklady na opravy ve výši 4 miliony. Ze zkušenosti účetní jednotky v minulosti a budoucího očekávání vyplývá, že v příštím roce nebude mít 75 procent prodaných výrobků žádné vady, 20 procent prodaných výrobků bude mít malé závady a 5 procent prodaných výrobků bude mít velké závady. V souladu s odstavcem 24 bude účetní jednotka posuzovat pravděpodobnost odtoku za všechny záruční závazky jako celek. Očekávané náklady na opravy činí: (75 % z nuly) + (20 % z 1 mil.) + (5 % ze 4 mil.) = 400 000 40 41 Rizika a nejistoty 42 43 44 Současná hodnota 45 46 47 Budoucí události 48 49 50 Očekávané vyřazení aktiv 51 52'),
('75f32510-475f-454b-aa80-b275b49f9828', 7, 'NÁHRADY', '53 54 55 56 57 58'),
('75f32510-475f-454b-aa80-b275b49f9828', 8, 'ÚPRAVY REZERV', '59 60'),
('75f32510-475f-454b-aa80-b275b49f9828', 9, 'POUŽITÍ REZERV', '61 62'),
('75f32510-475f-454b-aa80-b275b49f9828', 10, 'APLIKACE PRAVIDEL UZNÁVÁNÍ A OCEŇOVÁNÍ', 'Budoucí provozní ztráty 63 64 65 Nevýhodné smlouvy 66 67 68 68A a) mezní náklady na plnění takové smlouvy – jako jsou přímé osobní náklady a materiál – a b) přiřazení dalších nákladů, které přímo souvisejí s plněním smlouvy – například přiřazení odpisů za položku pozemků, budov a zařízení, které byly mimo jiné použity při plnění této smlouvy. 69 Restrukturalizace 70 a) prodej nebo ukončení části podnikatelských aktivit; b) uzavření podnikatelských provozů v některé zemi nebo oblasti nebo přemístění podnikatelských aktivit z jedné země nebo oblasti do jiné; c) změny ve struktuře vedení účetní jednotky, například zrušení některé úrovně řízení, a d) zásadní reorganizace, která má významný dopad na podstatu a zaměření činnosti účetní jednotky. 71 72 a) má oficiální podrobný plán restrukturalizace, který určuje přinejmenším: i) obor nebo část oboru, kterým se zabývá; ii) hlavní místo, kterého se týká; iii) umístění, funkci a přibližný počet zaměstnanců, kteří budou odškodněni z důvodu zrušení jejich míst; iv) výdaje, které budou vynaloženy, a v) dobu, kdy bude plán implementován, a b) u těch, kterých se to týká, vyvolala reálné očekávání, že restrukturalizace bude provedena, a to tím, že zahájila implementaci jejího plánu nebo zveřejnila její hlavní rysy těm, kteří jí budou ovlivněni. 73 74 75 a) zahájila implementaci plánu restrukturalizace, nebo b) oznámila dostatečně specifickým způsobem hlavní znaky plánu restrukturalizace těm, kterých se bude týkat, a to tak, že u nich vyvolala reálné očekávání, že restrukturalizaci provede.'),
('75f32510-475f-454b-aa80-b275b49f9828', 11, 'APLIKACE PRAVIDEL UZNÁVÁNÍ A OCEŇOVÁNÍ', 'Pokud účetní jednotka začne provádět plán restrukturalizace nebo oznámí jeho hlavní znaky těm, kterých se bude týkat, až po účetním období, je vyžadováno zveřejnění podle IAS 10 Události po skončení účetního období, pokud je restrukturalizace významná a pokud by bylo možné rozumně očekávat, že nezveřejnění těchto informací ovlivní rozhodnutí, která primární uživatelé obecné účetní závěrky činí na základě účetní závěrky, která poskytuje finanční informace o konkrétní vykazující účetní jednotce. 76 77 78 79 80 a) nezbytně nutné pro provedení restrukturalizace a b) nejsou spojeny s pokračujícími aktivitami účetní jednotky. 81 a) přeškolení nebo přemístění zaměstnanců, kteří budou v práci pokračovat; b) marketing nebo c) investice do nových systémů a distribučních sítí. Tyto výdaje jsou spojeny s budoucím provozováním podnikatelských aktivit a nejsou ke konci účetního období závazkem z titulu restrukturalizace. Takové výdaje se uznávají na stejném základě, jako kdyby k nim došlo nezávisle na restrukturalizaci. 82 83'),
('75f32510-475f-454b-aa80-b275b49f9828', 12, 'ZVEŘEJNĚNÍ', '84 a) účetní hodnotu na začátku a na konci účetního období; b) rezervy vytvořené nově v průběhu účetního období včetně přírůstku stávajících rezerv; c) částky, které byly v průběhu účetního období čerpány (tj. vydány a zúčtovány proti rezervě); d) nevyčerpané částky rezerv, které byly v průběhu účetního období zrušeny, a e) přírůstky diskontované výše rezervy za účetní období, ke kterým došlo z důvodu plynutí času, a dopad jakýchkoli změn diskontní sazby. Srovnávací informace se nepožadují. 85 a) stručný popis podstaty závazku a očekávaný časový rozvrh všech výsledných odtoků ekonomického prospěchu; b) nejistoty ve výši nebo časovém rozvrhu těchto odtoků. Pokud je to pro poskytnutí odpovídající informace nezbytné, zveřejní účetní jednotka hlavní předpoklady týkající se budoucích událostí tak, jak je stanoveno odstavcem 48, a c) částku všech očekávaných náhrad s uvedením částky všech aktiv, které byly z důvodu těchto očekávaných náhrad uznány. 86 a) odhad jeho finančního dopadu, vyčíslený podle odstavců 36–52; b) nejistoty týkající se výše nebo časového rozvrhu veškerých odtoků a c) možnost všech případných náhrad. 87 88 89 90 91 92'),
('75f32510-475f-454b-aa80-b275b49f9828', 13, 'PŘECHODNÁ USTANOVENÍ', '93 94 94A'),
('75f32510-475f-454b-aa80-b275b49f9828', 14, 'DATUM ÚČINNOSTI', '95 96 97 98 99 100 101 102 103 104 105')
